const root=document.getElementById('study'),el=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
const random=new Uint32Array(1);crypto.getRandomValues(random);const assignment=random[0]%4;
const result={schema:'btr.viewer-study.v2',version:STUDY_VERSION,participant:crypto.randomUUID(),assignment,consent:false,trials:[]};
let index=0,pack=null;
document.getElementById('start').onclick=async()=>{if(!document.getElementById('consent').checked){document.getElementById('status').textContent='Please confirm your choice to take part.';return;}result.consent=true;result.familiarity=document.getElementById('familiarity').value;try{pack=await fetch('assets/btr-agent-evaluation.json').then(r=>r.ok?r.json():null);}catch{}renderTrial();};
function renderTrial(){const a=studyAssignment(assignment)[index],c=STUDY_CASES.find(c=>c.id===a.case_id),input={scenario:c.id,time:c.time,language:'en',mode:'analyst',team:'harbor',focus:c.id==='press'?8:7,corrected:false},story=matchStory(input);root.replaceChildren(el('p',`TASK ${index+1} / 2 · SYNTHETIC FOOTBALL`),el('h1',c.title),el('p','Read the information below, then answer without help. There is no need to rush.'));
const source=el('section');source.className='source-card';source.append(el('strong',story.analysis.focus.value),el('b',story.analysis.focus.label),el('code',story.equation),el('p',story.stats),el('p',story.football.observation||story.body),el('p',story.review.reason),el('small','Synthetic records. The film is not used to measure these events.'));root.append(source);
let contentKind='records-only';if(a.condition==='crew'){const row=pack?.cases?.find(r=>r.input.scenario===c.id&&r.input.time===c.time&&r.input.language==='en'&&!r.input.corrected),posts=row?.team?.posts||localPanel(story);contentKind=row?'saved-model-run-with-calculated-and-reviewed-contributions':'reviewed-notes';root.append(el('h2','The crew’s explanation'));for(const p of posts){const card=el('article');card.className='study-post';card.append(el('strong',({analyst:'SCOUT',guide:'GUIDE',math:'VECTOR',reviewer:'CHECK',presenter:'HOST'})[p.role]),el('p',p.summary),el('small',p.engine==='azure_openai'?'Saved AI contribution':p.engine==='calculated'?'Calculated from records':'Reviewed explanation'));root.append(card);}}
const began=performance.now(),form=el('form'),answers={};for(const q of c.questions){const field=el('fieldset');field.append(el('legend',q.text));q.choices.forEach((text,i)=>{const label=el('label'),radio=el('input');radio.type='radio';radio.name=q.id;radio.required=true;radio.onchange=()=>answers[q.id]=i;label.append(radio,document.createTextNode(text));field.append(label);});form.append(field);}const button=el('button',index===0?'Save answers · next task →':'Save answers · finish →');form.append(button);root.append(form);form.onsubmit=e=>{e.preventDefault();result.trials.push({...scoreStudyTrial(c.id,answers),condition:a.condition,content_kind:contentKind,content_version:pack?.policy||'reviewed-v43',elapsed_seconds:Math.round((performance.now()-began)/1000)});index++;window.scrollTo(0,0);index<2?renderTrial():finish();};}
function finish(){root.replaceChildren(el('p','THANK YOU / TWO TASKS COMPLETE'),el('h1','Tell us what helped.'),el('p','Your results have not been sent. Download them only if you want to share them with the project creator.'));const form=el('form'),label=el('label','How useful was the crew’s explanation?'),rating=el('select');rating.required=true;for(const [value,text]of [['','Choose a rating'],['1','1 · Not useful'],['2','2'],['3','3 · Somewhat useful'],['4','4'],['5','5 · Very useful']]){const o=el('option',text);o.value=value;rating.append(o);}label.append(rating);const feedbackLabel=el('label','What was confusing or worth keeping? Optional; please omit personal details.'),feedback=el('textarea');feedback.maxLength=1000;feedbackLabel.append(feedback);const download=el('button','Download my anonymous results ↓');form.append(label,feedbackLabel,download);root.append(form);form.onsubmit=e=>{e.preventDefault();result.usefulness=Number(rating.value);result.feedback=feedback.value;result.completed_at=new Date().toISOString();const blob=new Blob([JSON.stringify(result,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='btr-viewer-'+result.participant+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};const details=el('details');details.append(el('summary','See the answers after both tasks'));for(const c of STUDY_CASES)for(const q of c.questions)details.append(el('p',q.text+' '+q.choices[q.answer]));root.append(details);}
